using System.Security.Claims; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using OCRS.Data;
namespace OCRS.Areas.Instructor.Controllers;
[Area("Instructor"),Authorize(Roles="Instructor")] public class MyClassesController(ApplicationDbContext db):Controller { public async Task<IActionResult> Index(){var uid=User.FindFirstValue(ClaimTypes.NameIdentifier);return View(await db.CourseClasses.Include(x=>x.Course).Include(x=>x.Enrollments).Where(x=>x.Instructor!.UserId==uid).ToListAsync());} public async Task<IActionResult> Details(int id){var uid=User.FindFirstValue(ClaimTypes.NameIdentifier);var x=await db.CourseClasses.Include(x=>x.Enrollments).ThenInclude(x=>x.Student).ThenInclude(x=>x.User).SingleOrDefaultAsync(x=>x.ClassId==id&&x.Instructor!.UserId==uid);return x==null?NotFound():View(x);} }
